import json

# Build output grid
H, W = 27, 22

# Frame column positions (every 5 cols)
frame_cols = [0, 5, 10, 15, 20]

# Frame row positions (rows with no 3s)
frame_rows = {1, 5, 9, 13, 17, 21, 25}

output = []
for r in range(H):
    if r in frame_rows:
        # Frame row: markers become 9 at frame cols, 7 elsewhere
        row = []
        for c in range(W):
            if c in frame_cols:
                row.append(9)
            else:
                row.append(7)
    else:
        # Open row: all 7s
        row = [7] * W
    output.append(row)

# Verify frame row structure
print("Frame row pattern:")
for r in frame_rows:
    print(f"Row {r}: {output[r]}")

print("\nOpen row pattern:")
for r in [0, 2, 26]:
    print(f"Row {r}: {output[r]}")

